use axum::body::Body;
use axum::extract::{Path, Query, State};
use axum::http::{HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};
use axum::Json;
use futures::StreamExt;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Arc;

use crate::error::ServiceResult;
use crate::metadata::Bucket;
use crate::service::ObjectStoreService;

pub type SharedService = Arc<ObjectStoreService>;

#[derive(Debug, Serialize, Deserialize)]
pub struct CreateBucketRequest {
    pub name: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct BucketResponse {
    pub id: String,
    pub name: String,
    pub created_at: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ListBucketsResponse {
    pub buckets: Vec<BucketResponse>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ObjectMetadataResponse {
    pub key: String,
    pub size: u64,
    pub content_type: Option<String>,
    pub etag: String,
    pub last_modified: String,
    pub metadata: HashMap<String, String>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ListObjectsResponse {
    pub objects: Vec<ObjectMetadataResponse>,
    pub next_continuation_token: [REDACTED],
}

#[derive(Debug, Deserialize)]
pub struct ListObjectsQuery {
    pub prefix: Option<String>,
    pub max_keys: Option<usize>,
    pub continuation_token: [REDACTED],
}

#[derive(Debug, Serialize, Deserialize)]
pub struct DeleteObjectsRequest {
    pub keys: Vec<String>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct CopyObjectRequest {
    pub source_bucket: String,
    pub source_key: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct DeleteObjectResultResponse {
    pub key: String,
    pub deleted: bool,
    pub error: Option<String>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct DeleteObjectsResponse {
    pub results: Vec<DeleteObjectResultResponse>,
    pub deleted: usize,
    pub failed: usize,
}

#[derive(Debug, Deserialize)]
pub struct GetPublicUrlQuery {
    pub expiration_secs: Option<u64>,
    pub purpose: Option<object_store_backends::PublicUrlPurpose>,
}

#[derive(Debug, Serialize)]
pub struct PublicUrlResponse {
    pub url: String,
    pub expires_in: u64,
}

impl From<Bucket> for BucketResponse {
    fn from(bucket: Bucket) -> Self {
        Self {
            id: bucket.id,
            name: bucket.name,
            created_at: bucket.created_at,
        }
    }
}

impl From<object_store_backends::ObjectMetadata> for ObjectMetadataResponse {
    fn from(metadata: object_store_backends::ObjectMetadata) -> Self {
        Self {
            key: metadata.key,
            size: metadata.size,
            content_type: metadata.content_type,
            etag: metadata.etag,
            last_modified: metadata.last_modified.to_rfc3339(),
            metadata: metadata.custom_metadata,
        }
    }
}

pub async fn health_check() -> impl IntoResponse {
    Json(serde_json::json!({
        "status": "healthy",
        "service": "object-store"
    }))
}

pub async fn create_bucket(
    State(service): State<SharedService>,
    Json(payload): Json<CreateBucketRequest>,
) -> ServiceResult<Json<BucketResponse>> {
    let bucket = service.create_bucket(&payload.name).await?;
    Ok(Json(bucket.into()))
}

pub async fn upsert_bucket(
    State(service): State<SharedService>,
    Json(payload): Json<CreateBucketRequest>,
) -> ServiceResult<Json<BucketResponse>> {
    let bucket = service.upsert_bucket(&payload.name).await?;
    Ok(Json(bucket.into()))
}

pub async fn list_buckets(
    State(service): State<SharedService>,
) -> ServiceResult<Json<ListBucketsResponse>> {
    let buckets = service.list_buckets().await?;
    let response = ListBucketsResponse {
        buckets: buckets.into_iter().map(|b| b.into()).collect(),
    };
    Ok(Json(response))
}

pub async fn get_bucket_by_id(
    State(service): State<SharedService>,
    Path(id): Path<String>,
) -> ServiceResult<Json<BucketResponse>> {
    let bucket = service.get_bucket_by_id(&id).await?;
    Ok(Json(bucket.into()))
}

pub async fn delete_bucket(
    State(service): State<SharedService>,
    Path(bucket): Path<String>,
) -> ServiceResult<StatusCode> {
    service.delete_bucket(&bucket).await?;
    Ok(StatusCode::NO_CONTENT)
}

pub async fn put_object(
    State(service): State<SharedService>,
    Path((bucket, key)): Path<(String, String)>,
    headers: HeaderMap,
    body: Body,
) -> ServiceResult<Json<ObjectMetadataResponse>> {
    // Extract content type from headers
    let content_type = headers
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .map(|s| s.to_string())
        .or_else(|| {
            // Try to guess content type from file extension
            mime_guess::from_path(&key).first().map(|m| m.to_string())
        });

    // Extract custom metadata from headers (x-amz-meta-* pattern)
    let mut metadata = HashMap::new();
    for (header_key, value) in headers.iter() {
        if let Some(meta_key) = header_key.as_str().strip_prefix("x-object-meta-") {
            if let Ok(meta_value) = value.to_str() {
                metadata.insert(meta_key.to_string(), meta_value.to_string());
            }
        }
    }

    let stream: object_store_backends::ByteStream = Box::pin(
        body.into_data_stream()
            .map(|result| result.map_err(std::io::Error::other)),
    );

    let obj_metadata = service
        .put_object(&bucket, &key, stream, content_type, metadata)
        .await?;

    Ok(Json(obj_metadata.into()))
}

pub async fn get_object(
    State(service): State<SharedService>,
    Path((bucket, key)): Path<(String, String)>,
) -> ServiceResult<Response> {
    let obj_data = service.get_object(&bucket, &key).await?;

    let mut headers = HeaderMap::new();

    if let Some(ct) = obj_data.metadata.content_type {
        if let Ok(header_value) = ct.parse() {
            headers.insert("content-type", header_value);
        }
    }

    headers.insert(
        "etag",
        obj_data
            .metadata
            .etag
            .parse()
            .unwrap_or_else(|_| "unknown".parse().unwrap()),
    );

    headers.insert(
        "last-modified",
        obj_data
            .metadata
            .last_modified
            .to_rfc2822()
            .parse()
            .unwrap_or_else(|_| "unknown".parse().unwrap()),
    );

    headers.insert(
        "content-length",
        obj_data
            .metadata
            .size
            .to_string()
            .parse()
            .unwrap_or_else(|_| "0".parse().unwrap()),
    );

    // Add custom metadata as x-object-meta-* headers
    for (key, value) in obj_data.metadata.custom_metadata.iter() {
        let header_name = format!("x-object-meta-{}", key);
        if let Ok(header_value) = value.parse() {
            if let Ok(header_name) = header_name.parse::<axum::http::HeaderName>() {
                headers.insert(header_name, header_value);
            }
        }
    }

    let body = Body::from_stream(obj_data.stream);

    Ok((headers, body).into_response())
}

pub async fn get_object_info(
    State(service): State<SharedService>,
    Path((bucket, key)): Path<(String, String)>,
) -> ServiceResult<Json<ObjectMetadataResponse>> {
    let metadata = service.head_object(&bucket, &key).await?;
    Ok(Json(metadata.into()))
}

pub async fn head_object(
    State(service): State<SharedService>,
    Path((bucket, key)): Path<(String, String)>,
) -> ServiceResult<Response> {
    let metadata = service.head_object(&bucket, &key).await?;

    let mut headers = HeaderMap::new();

    if let Some(ct) = metadata.content_type {
        if let Ok(header_value) = ct.parse() {
            headers.insert("content-type", header_value);
        }
    }

    headers.insert(
        "etag",
        metadata
            .etag
            .parse()
            .unwrap_or_else(|_| "unknown".parse().unwrap()),
    );

    headers.insert(
        "last-modified",
        metadata
            .last_modified
            .to_rfc2822()
            .parse()
            .unwrap_or_else(|_| "unknown".parse().unwrap()),
    );

    headers.insert(
        "content-length",
        metadata
            .size
            .to_string()
            .parse()
            .unwrap_or_else(|_| "0".parse().unwrap()),
    );

    // Add custom metadata as x-object-meta-* headers
    for (key, value) in metadata.custom_metadata.iter() {
        let header_name = format!("x-object-meta-{}", key);
        if let Ok(header_value) = value.parse() {
            if let Ok(header_name) = header_name.parse::<axum::http::HeaderName>() {
                headers.insert(header_name, header_value);
            }
        }
    }

    Ok((StatusCode::OK, headers).into_response())
}

pub async fn delete_object(
    State(service): State<SharedService>,
    Path((bucket, key)): Path<(String, String)>,
) -> ServiceResult<StatusCode> {
    service.delete_object(&bucket, &key).await?;
    Ok(StatusCode::NO_CONTENT)
}

pub async fn copy_object(
    State(service): State<SharedService>,
    Path((bucket, key)): Path<(String, String)>,
    Json(payload): Json<CopyObjectRequest>,
) -> ServiceResult<Json<ObjectMetadataResponse>> {
    let metadata = service
        .copy_object(&payload.source_bucket, &payload.source_key, &bucket, &key)
        .await?;

    Ok(Json(metadata.into()))
}

pub async fn delete_objects(
    State(service): State<SharedService>,
    Path(bucket): Path<String>,
    Json(payload): Json<DeleteObjectsRequest>,
) -> ServiceResult<Json<DeleteObjectsResponse>> {
    let results = service.delete_objects(&bucket, &payload.keys).await?;

    let deleted = results.iter().filter(|r| r.deleted).count();

    Ok(Json(DeleteObjectsResponse {
        failed: results.len() - deleted,
        deleted,
        results: results
            .into_iter()
            .map(|r| DeleteObjectResultResponse {
                key: r.key,
                deleted: r.deleted,
                error: r.error,
            })
            .collect(),
    }))
}

pub async fn list_objects(
    State(service): State<SharedService>,
    Path(bucket): Path<String>,
    Query(params): Query<ListObjectsQuery>,
) -> ServiceResult<Json<ListObjectsResponse>> {
    let page = service
        .list_objects(
            &bucket,
            params.prefix.as_deref(),
            params.max_keys,
            params.continuation_token.as_deref(),
        )
        .await?;

    let response = ListObjectsResponse {
        objects: page.objects.into_iter().map(|o| o.into()).collect(),
        next_continuation_token: [REDACTED],
    };

    Ok(Json(response))
}

pub async fn get_public_url(
    State(service): State<SharedService>,
    Path((bucket, key)): Path<(String, String)>,
    Query(params): Query<GetPublicUrlQuery>,
) -> ServiceResult<Json<PublicUrlResponse>> {
    // Default expiration is 1 hour (3600 seconds)
    let expiration_secs = params.expiration_secs.unwrap_or(3600);

    // Default purpose is retrieve
    let purpose = params
        .purpose
        .unwrap_or(object_store_backends::PublicUrlPurpose::Retrieve);

    let url = service
        .get_public_url(&bucket, &key, expiration_secs, purpose)
        .await?;

    Ok(Json(PublicUrlResponse {
        url,
        expires_in: expiration_secs,
    }))
}

# Object Storage Client for TypeScript

TypeScript/JavaScript client library for interacting with the [Metorial Object Storage Service](https://github.com/metorial/object-storage).

## Usage

```typescript
import { ObjectStorageClient } from 'object-storage-client';

const client = new ObjectStorageClient('http://localhost:8080');

// Create a bucket
const bucket = await client.createBucket('my-bucket');
console.log(`Created bucket: ${bucket.name}`);

// Upload an object
const data = Buffer.from('Hello, World!');
const obj = await client.putObject(
  'my-bucket',
  'hello.txt',
  data,
  'text/plain',
  { key1: 'value1' }
);
console.log(`Uploaded object: ${obj.key} (ETag: ${obj.etag})`);

// Download an object
const objData = await client.getObject('my-bucket', 'hello.txt');
console.log(`Downloaded ${objData.data.length} bytes`);

// List objects
const objects = await client.listObjects('my-bucket');
for (const obj of objects) {
  console.log(`${obj.key}: ${obj.size} bytes`);
}

// Delete object
await client.deleteObject('my-bucket', 'hello.txt');

// Delete bucket
await client.deleteBucket('my-bucket');
```

## API Reference

### Client Creation

```typescript
const client = new ObjectStorageClient('http://localhost:8080');
```

With custom timeout:

```typescript
const client = new ObjectStorageClient('http://localhost:8080', 60000);
```

### Bucket Operations

**Create Bucket**
```typescript
const bucket = await client.createBucket('bucket-name');
```

**List Buckets**
```typescript
const buckets = await client.listBuckets();
```

**Delete Bucket**
```typescript
await client.deleteBucket('bucket-name');
```

### Object Operations

**Put Object**
```typescript
const data = Buffer.from('content');
const obj = await client.putObject(
  'bucket-name',
  'object-key',
  data,
  'application/json',
  { key: 'value' }
);
```

**Get Object**
```typescript
const objData = await client.getObject('bucket-name', 'object-key');
// objData.data contains the object buffer
// objData.metadata contains metadata
```

**Head Object**
```typescript
const metadata = await client.headObject('bucket-name', 'object-key');
```

**Delete Object**
```typescript
await client.deleteObject('bucket-name', 'object-key');
```

**Delete Many Objects**
```typescript
const results = await client.deleteObjects('bucket-name', ['a.txt', 'b.txt']);
for (const result of results) {
  if (!result.deleted) console.log(`${result.key} failed: ${result.error}`);
}
```

**Copy Object**
```typescript
// Copies into 'bucket-name/skills/demo/asset.bin' from 'files/abc123'.
// The bytes are copied inside the object store, never through this process.
const metadata = await client.copyObject('bucket-name', 'skills/demo/asset.bin', 'files', 'abc123');
```

**List Objects**
```typescript
// List all objects, following pagination internally
const objects = await client.listObjects('bucket-name');

// List with prefix
const objects = await client.listObjects('bucket-name', 'prefix/');

// Stop after at most 100 objects
const objects = await client.listObjects('bucket-name', 'prefix/', 100);

// Drive pagination yourself
let token: string | undefined;
do {
  const page = await client.listObjectsPage('bucket-name', 'prefix/', 500, token);
  token = [REDACTED];
} while (token);
```

## Error Handling

The client throws `ObjectStorageError` for API errors:

```typescript
import { ObjectStorageError } from 'object-storage-client';

try {
  const obj = await client.getObject('bucket', 'key');
} catch (error) {
  if (error instanceof ObjectStorageError) {
    console.log(`Status: ${error.statusCode}, Message: ${error.message}`);
  }
}
```

# Object Storage Client for Rust

Async Rust client library for interacting with the [Metorial Object Storage Service](https://github.com/metorial/object-storage).

## Installation

Add to your `Cargo.toml`:

```toml
[dependencies]
object-store-client = "0.1"
tokio = { version = "1", features = ["full"] }
```

## Usage

```rust
use object_store_client::{ObjectStoreClient, Result};

#[tokio::main]
async fn main() -> Result<()> {
    let client = ObjectStoreClient::new("http://localhost:8080");

    // Create a bucket
    client.create_bucket("my-bucket").await?;

    // Upload an object
    let data = b"Hello, World!";
    client.put_object("my-bucket", "hello.txt", data, Some("text/plain"), None).await?;

    // Download an object
    let obj = client.get_object("my-bucket", "hello.txt").await?;
    println!("Downloaded {} bytes", obj.data.len());

    // List objects
    let objects = client.list_objects("my-bucket", None, None).await?;
    for obj in objects {
        println!("{}: {} bytes", obj.key, obj.size);
    }

    // Delete object
    client.delete_object("my-bucket", "hello.txt").await?;

    // Delete bucket
    client.delete_bucket("my-bucket").await?;

    Ok(())
}
```

## API Reference

### Client Creation

```rust
let client = ObjectStoreClient::new("http://localhost:8080");
```

### Bucket Operations

**Create Bucket**
```rust
client.create_bucket("bucket-name").await?;
```

**List Buckets**
```rust
let buckets = client.list_buckets().await?;
```

**Delete Bucket**
```rust
client.delete_bucket("bucket-name").await?;
```

### Object Operations

**Put Object**
```rust
let metadata = client.put_object(
    "bucket-name",
    "object-key",
    data,
    Some("application/json"),
    Some(custom_metadata)
).await?;
```

**Get Object**
```rust
let obj = client.get_object("bucket-name", "object-key").await?;
```

**Head Object**
```rust
let metadata = client.head_object("bucket-name", "object-key").await?;
```

**Delete Object**
```rust
client.delete_object("bucket-name", "object-key").await?;
```

**Delete Many Objects**
```rust
let results = client
    .delete_objects("bucket-name", &["a.txt".to_string(), "b.txt".to_string()])
    .await?;
```

**Copy Object**
```rust
// Copies into "bucket-name/skills/demo/asset.bin" from "files/abc123".
// The bytes are copied inside the object store, never through this process.
let metadata = client
    .copy_object("bucket-name", "skills/demo/asset.bin", "files", "abc123")
    .await?;
```

**List Objects**
```rust
// Follows pagination internally
let objects = client.list_objects("bucket-name", Some("prefix/"), Some(100)).await?;

// Or drive pagination yourself
let page = client
    .list_objects_page("bucket-name", Some("prefix/"), Some(500), None)
    .await?;
let next = page.next_continuation_token;
```

## Error Handling

The client returns `Result<T, Error>` where `Error` can be:

- `Error::NotFound` - Resource not found
- `Error::AlreadyExists` - Resource already exists
- `Error::BadRequest` - Invalid request
- `Error::ServerError` - Server error
- `Error::Http` - Network/HTTP error

# Object Storage Client for Go

Go client library for interacting with the [Metorial Object Storage Service](https://github.com/metorial/object-storage).

## Installation

```bash
go get github.com/metorial/object-storage/clients/go
```

## Usage

```go
package main

import (
    "fmt"
    "log"

    objectstorage "github.com/metorial/object-storage/clients/go"
)

func main() {
    client := objectstorage.NewClient("http://localhost:8080")

    // Create a bucket
    bucket, err := client.CreateBucket("my-bucket")
    if err != nil {
        log.Fatal(err)
    }
    fmt.Printf("Created bucket: %s\n", bucket.Name)

    // Upload an object
    data := []byte("Hello, World!")
    contentType := "text/plain"
    metadata := map[string]string{"key1": "value1"}

    obj, err := client.PutObject("my-bucket", "hello.txt", data, &contentType, metadata)
    if err != nil {
        log.Fatal(err)
    }
    fmt.Printf("Uploaded object: %s (ETag: %s)\n", obj.Key, obj.ETag)

    // Download an object
    objData, err := client.GetObject("my-bucket", "hello.txt")
    if err != nil {
        log.Fatal(err)
    }
    fmt.Printf("Downloaded %d bytes\n", len(objData.Data))

    // List objects
    objects, err := client.ListObjects("my-bucket", nil, nil)
    if err != nil {
        log.Fatal(err)
    }
    for _, obj := range objects {
        fmt.Printf("%s: %d bytes\n", obj.Key, obj.Size)
    }

    // Delete object
    if err := client.DeleteObject("my-bucket", "hello.txt"); err != nil {
        log.Fatal(err)
    }

    // Delete bucket
    if err := client.DeleteBucket("my-bucket"); err != nil {
        log.Fatal(err)
    }
}
```

## API Reference

### Client Creation

```go
client := objectstorage.NewClient("http://localhost:8080")
```

For custom HTTP client configuration:

```go
httpClient := &http.Client{Timeout: 60 * time.Second}
client := objectstorage.NewClientWithHTTP("http://localhost:8080", httpClient)
```

### Bucket Operations

**Create Bucket**
```go
bucket, err := client.CreateBucket("bucket-name")
```

**List Buckets**
```go
buckets, err := client.ListBuckets()
```

**Delete Bucket**
```go
err := client.DeleteBucket("bucket-name")
```

### Object Operations

**Put Object**
```go
data := []byte("content")
contentType := "application/json"
metadata := map[string]string{"key": "value"}

obj, err := client.PutObject("bucket-name", "object-key", data, &contentType, metadata)
```

**Get Object**
```go
objData, err := client.GetObject("bucket-name", "object-key")
// objData.Data contains the object bytes
// objData.Metadata contains metadata
```

**Head Object**
```go
metadata, err := client.HeadObject("bucket-name", "object-key")
```

**Delete Object**
```go
err := client.DeleteObject("bucket-name", "object-key")
```

**Delete Many Objects**
```go
results, err := client.DeleteObjects("bucket-name", []string{"a.txt", "b.txt"})
for _, result := range results {
    if !result.Deleted {
        log.Printf("%s failed: %s", result.Key, *result.Error)
    }
}
```

**Copy Object**
```go
// Copies into "bucket-name/skills/demo/asset.bin" from "files/abc123".
// The bytes are copied inside the object store, never through this process.
metadata, err := client.CopyObject("bucket-name", "skills/demo/asset.bin", "files", "abc123")
```

**List Objects**
```go
// List all objects, following pagination internally
objects, err := client.ListObjects("bucket-name", nil, nil)

// List with prefix
prefix := "prefix/"
objects, err := client.ListObjects("bucket-name", &prefix, nil)

// Stop after at most 100 objects
maxKeys := 100
objects, err := client.ListObjects("bucket-name", &prefix, &maxKeys)

// Drive pagination yourself
var token *string
for {
    page, err := client.ListObjectsPage("bucket-name", &prefix, nil, token)
    if err != nil || page.NextContinuationToken == nil {
        break
    }
    token = [REDACTED]
}
```

## Error Handling

The client returns typed errors:

```go
obj, err := client.GetObject("bucket", "key")
if err != nil {
    if objErr, ok := err.(*objectstorage.Error); ok {
        fmt.Printf("Status: %d, Message: %s\n", objErr.StatusCode, objErr.Message)
    }
}
```

